import{_ as o,l,o as e,c as s,v as t,p as h,x as i,d as n,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"掩模写入时间与产能","description":"","frontmatter":{"title":"掩模写入时间与产能","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-write-time.md","filePath":"litho/mask-write-time.md","lastUpdated":1789023840000}'),m={name:"litho/mask-write-time.md"};function E(c,a,A,_,u,f){const r=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="掩模写入时间与产能" tabindex="-1">掩模写入时间与产能 <a class="header-anchor" href="#掩模写入时间与产能" aria-label="Permalink to &quot;掩模写入时间与产能&quot;">​</a></h1><div class="epigraph"><p>VSB 的日历跟炮数走；多束的日历跟面积与剂量走。同一张 ILT 版，换家族等于换哪堵墙先撞上。</p><footer>—— 对照电子束掩模写入产能与多束对复杂度解耦的公开论述</footer></div><p><a href="/litho/curvilinear-data-volume">上一课</a>把曲线层的体积钉成栅格账。缺口是体积还要变成写模机小时：掩模厂的瓶颈机台、客户的 TAPOUT 日历、以及「改一版要等多久」。本课钉写入时间。PEC 核怎么吃进这些小时，留给[下一课](/litho/mask-pec-detail）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/multibeam-mask-writer">多束写掩模</a> 已经声明家族差异。本课把它收成产能公式。VSB：时间近似正比于炮数 / 电流，再加场间移动、校准与雾化校正开销。多束：时间近似正比于曝光面积 × 剂量 / 总束流，图形复杂度进入的是数据解码，不是主项。胶灵敏度、加速电压、多层扫描（为了降粗糙或做灰度）把同一公式再乘系数。</p><p>缺口是<strong>可预测日历</strong>，不是再夸一次曲线漂亮。把写模机 wph 理解成晶圆扫描机 wph，单位都错：一张关键层版可以写十小时量级，厂里同时只有有限台写入器。</p><h3 id="剂量不是免费的-cd" tabindex="-1">剂量不是免费的 CD <a class="header-anchor" href="#剂量不是免费的-cd" aria-label="Permalink to &quot;剂量不是免费的 CD&quot;">​</a></h3><p>为了 CDU 或 PEC 动态范围加剂量、做多遍扫描，写入时间几乎线性涨。EUV 厚胶或低灵敏度胶更明显。产能规划若只按「层数 × 平均 8 小时」而不按剂量与多遍，会在 EUV 与 ILT 层上集体误期。</p><p><span class="marginnote">简单接触层用 VSB 可能更快：单炮面积大。用全厂多束去写稀疏版，是买错组合。对照上一课：复杂度尾部才是多束的产能理由。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>排产：按层类型分家族（曼哈顿 VSB / 曲线多束），用历史炮密度或开口率预测时间，再加检验与清洗队列。返工（CD 超差、缺陷修复后再写）必须进周期，不能只报一次通过。与 <a href="/litho/high-na-throughput-economics">高 NA 经济</a> 衔接：晶圆 wph 再高，等版的日子仍在关键路径上。</p><p>数据就绪是隐藏前置：MDP 没跑完，写入器空转。曲线层的解码带宽若低于曝光带宽，多束会从面积墙退回数据墙。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>电子束电流受库仑效应与分辨率约束，不能靠「把电流开到最大」无限缩短时间。多束用空间并行换时间；总电流仍受光学与抗蚀剂加热限制——写太快会热漂移，配准变差。因此写入时间与 <a href="/litho/mask-registration">mask registration</a> 在同一张物理预算里：不是越快越好。</p>',14)),(e(),h(p,null,{default:i(()=>[d(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20VSB%5B%22VSB%3A%20t%20~%20%E7%82%AE%E6%95%B0%20%2F%20%E7%94%B5%E6%B5%81%22%5D%20--%3E%20CAL%5B%22%E5%86%99%E5%85%A5%E6%97%A5%E5%8E%86%22%5D%0A%20%20MB%5B%22%E5%A4%9A%E6%9D%9F%3A%20t%20~%20%E9%9D%A2%E7%A7%AF%20%C3%97%20%E5%89%82%E9%87%8F%22%5D%20--%3E%20CAL%0A%20%20DATA%5B%22MDP%20%2F%20%E8%A7%A3%E7%A0%81%22%5D%20--%3E%20CAL%0A%20%20CAL%20--%3E%20QUEUE%5B%22%E6%A3%80%E9%AA%8C%20%E6%B8%85%E6%B4%97%20%E8%BF%94%E5%B7%A5%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不编造某型号的小时数表。公开叙事只支持家族公式与量级，不支持把竞品规格抄成宇宙常数。写入时间不包含空白片交期与 pellicle 安装。</p><p>后课默认：产能公式已按家族分开；PEC 的计算与多遍扫描如何改剂量图，下一课补细节。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VSB 时间跟炮数走，多束时间跟面积与剂量走。</li><li>多遍与低灵敏度胶几乎线性拉长日历。</li><li>过快写入会以热漂移换配准；日历与 overlay 预算耦合。</li><li>出处：VSB / 多束掩模写入产能的公开论述；SPIE Photomask。</li></ul>',5))])}const T=o(m,[["render",E]]);export{P as __pageData,T as default};
